pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        // 1. Keep the domain wide: amounts can be large but bounded to avoid overflows in reference's add_uint256.
        // The only assumption needed: vault must be non-zero, and MinSum must be settable before Collect.
        vm.assume(minSum > 0);
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(putAmount <= type(uint256).max - collectAmount);
        bound(lockTime, 0, type(uint128).max);
        vm.assume(putAmount >= collectAmount);
        vm.assume(minSum <= putAmount);

        // 2. Setup: initialize, set MinSum, and fund a user.
        address user = address(0x1234);
        vm.deal(user, putAmount);

        c.Initialized();
        // Setting MinSum with the fuzzed value.
        // In the mutant, this call does nothing.
        c.SetMinSum(minSum);

        vm.warp(1000);
        vm.prank(user);
        c.Put{value: putAmount}(lockTime);

        // 3. The property: after these steps, any Collect call that observes the state will either succeed in reference
        // or revert in mutant. We check that a Collect call that should pass in reference (acc.balance >= MinSum && block.timestamp > unlockTime)
        // succeeds in reference, but fails in mutant because MinSum remains 0 and the condition acc.balance >= 0 holds,
        // but the bug manifests as a different MinSum state after. To catch the difference without relying on revert alone,
        // we read the public MinSum after a Collect attempt. In reference MinSum == minSum, while in mutant it stays 0.
        // However, the adversarial condition requires Collect to actually attempt a transfer.
        // We ensure that timestamp > unlockTime so the only barrier is MinSum being properly set.
        // The user's unlockTime is block.timestamp + lockTime from Put. If we advance time past that, Collect can proceed.
        vm.warp(1000 + lockTime + 1);

        // The collect should succeed in reference (all conditions met). We attempt it.
        vm.prank(user);
        try c.Collect(collectAmount) {
            // Collect succeeded, we read MinSum afterwards
        } catch {
            // In mutant, Collect might revert because acc.balance >= MinSum is false since MinSum==0 and balance>=_am, but
            // the revert reason might be from sub_uint256 or other checks. Actually in mutant MinSum==0, so acc.balance >= 0 holds,
            // and it proceeds to transfer. Wait: in mutant, SetMinSum does nothing, so MinSum == 0.
            // Then acc.balance (putAmount) >= 0 (true), acc.balance >= collectAmount (true), timestamp > unlockTime (true).
            // So mutant also succeeds! The difference is only in the state variable MinSum after.
            // So the catch is not needed; we just check state.
        }

        // The universal property: after any such sequence, the reference's MinSum equals the value set, whereas mutant's MinSum is 0.
        // But we want a property that holds for ALL inputs in reference AND breaks for SOME in mutant.
        // Reference always has MinSum == minSum after SetMinSum and no other setter. Mutant always has MinSum == 0.
        // So assert: MinSum != 0 iff SetMinSum was called with positive value and initialization occurred.
        // We can assert: if minSum > 0, then c.MinSum() == minSum in reference, but in mutant c.MinSum() == 0.
        // Since we assumed minSum > 0, the assertion c.MinSum() > 0 passes in reference, fails in mutant.
        assertTrue(c.MinSum() > 0);
    }
}

