contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 newMin) public {
        // Restrict to admissible values: am > 0, newMin different from current MinSum
        vm.assume(am > 0);
        vm.assume(newMin > 0);
        // Deploy a reentrant attacker that calls SetMinSum on collect
        ReenterAttacker attacker = new ReenterAttacker(address(c));
        // Setup: initialize contract
        c.Initialized();
        c.SetLogFile(address(this));
        // Set initial MinSum to something positive (e.g., 1) so that condition acc.balance >= MinSum can be met
        c.SetMinSum(1);
        // Give the attacker some ether and let it Put so it has balance and unlock condition
        vm.deal(address(attacker), am + 1 ether);
        attacker.put{value: am}();
        // Warp past unlock time
        vm.warp(block.timestamp + 1 days);
        // Record MinSum before collect
        uint256 minBefore = c.MinSum();
        // Attacker collects, triggering reentrant call that sets MinSum to newMin
        attacker.collect(am, newMin);
        uint256 minAfter = c.MinSum();
        // After collect, MinSum should still be 1 (reference) but buggy version may change it
        assertTrue(minBefore == minAfter);
    }
